  CONSTRAINT `inventory_stocks_warehouse_id_foreign` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `chk_inventory_stocks_qty` CHECK ((`quantity` >= 0)),
  CONSTRAINT `chk_inventory_stocks_value` CHECK (((`total_value` >= 0) and ((`quantity` > 0) or (`total_value` = 0))))
) ENGINE=InnoDB AUTO_INCREMENT=1269 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
