CREATE TABLE `stock_transfer_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `stock_transfer_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned NOT NULL,
  `quantity` decimal(15,3) NOT NULL,
  `qty_sent` decimal(15,3) NOT NULL DEFAULT '0.000',
  `qty_received` decimal(15,3) NOT NULL DEFAULT '0.000',
  `qty_returned` decimal(15,3) NOT NULL DEFAULT '0.000',
  `value_sent` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `value_received` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `value_returned` decimal(18,4) NOT NULL DEFAULT '0.0000',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `stock_transfer_items_stock_transfer_id_product_id_unique` (`stock_transfer_id`,`product_id`),
  KEY `stock_transfer_items_product_id_foreign` (`product_id`),
  CONSTRAINT `stock_transfer_items_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `stock_transfer_items_stock_transfer_id_foreign` FOREIGN KEY (`stock_transfer_id`) REFERENCES `stock_transfers` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `chk_st_items_flow` CHECK (((`qty_sent` >= 0) and (`qty_received` >= 0) and (`qty_returned` >= 0) and ((`qty_received` + `qty_returned`) <= `qty_sent`))),
  CONSTRAINT `chk_st_items_qty` CHECK ((`quantity` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
